mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END
FROM proveedor_servicio ps
WHERE ps.id = #{servicioId}
  AND ps.proveedor_id = #{proveedorId}
  AND ps.deleted = FALSE
  AND ps.activo = TRUE

mapper.update:
UPDATE promocion
SET deleted = TRUE, updated_at = NOW(), version = version + 1
WHERE id = #{id}
